          ]
        },
        {
          "proposicao": "No modo de aproamento fixo, a manutenção de um heading imposto pelo operador pode elevar consideravelmente a demanda de potência quando houver mudança significativa na incidência dos agentes ambientais, conectando escolha de modo de controle ao risco de perda de margem operacional.",
          "trechos": [
            "Ea7be1e0439e1ad4c:1397:2091",
            "Ea7be1e0439e1ad4c:2091:2272"
          ],
          "condicoes": [
            "Valor de aproamento mantido pelo operador do SPD",
            "Mudança significativa de direção dos agentes ambientais"
          ],
          "limites": [
            "O aumento de potência é qualitativo no trecho recuperado",
            "Não há limiar operacional ou gatilho de abortamento informado"
          ]
        }
      ]
